import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"指标与面板：空图、统计口径与故障复盘","description":"围绕原始指标、查询和面板身份定位异常。","frontmatter":{"title":"指标与面板：空图、统计口径与故障复盘","description":"围绕原始指标、查询和面板身份定位异常。","showdocs":{"topics":[{"id":"metrics","title":"指标与可视化","link":"/topics/metrics/"}],"kind":"排错与诊断","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"指标与可视化机制与任务课程","summary":"围绕原始指标、查询和面板身份定位异常。","status":"active","related":[{"title":"指标：序列、标签、Counter 与直方图","link":"/systems/logging-monitoring/metrics/metric-model","kind":"知识专题","scope":"general","audience":"general"},{"title":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"Grafana 多数据源与面板配置","link":"/systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations"},"next":false},"headers":[],"relativePath":"systems/logging-monitoring/metrics/diagnosis.md","filePath":"systems/logging-monitoring/metrics/diagnosis.md"}'),n={name:"systems/logging-monitoring/metrics/diagnosis.md"};function s(o,e,l,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="指标与面板-空图、统计口径与故障复盘" tabindex="-1">指标与面板：空图、统计口径与故障复盘 <a class="header-anchor" href="#指标与面板-空图、统计口径与故障复盘" aria-label="Permalink to &quot;指标与面板：空图、统计口径与故障复盘&quot;">​</a></h1><h2 id="part-1" tabindex="-1">空图、计数重置与单位错误定位 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;空图、计数重置与单位错误定位 {#part-1}&quot;">​</a></h2><p>本节沿原始序列、rate 聚合、空数据和面板单位定位失败层；先确认指标类型/单位、抓取窗口与数据源 UID，与<a href="/systems/logging-monitoring/metrics/plus/practice/application#source">配套示例</a>逐项对照，再选择最小修复。</p><p>核对日期2026-10-17；适用范围：机制按核对时Prometheus 3.x官方文档的稳定共同子集说明；示例另固定Prometheus 2.55与Grafana OSS 11.6教学配置族，归档族不是生产安装建议。新版新增或实验功能未默认启用，实际升级仍需独立兼容与安全评估。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/logging-monitoring/metrics/metric-model#part-1-model">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-1-empty" tabindex="-1">空图分层定位 <a class="header-anchor" href="#part-1-empty" aria-label="Permalink to &quot;空图分层定位 {#part-1-empty}&quot;">​</a></h3><p>指标空图排查从原始序列开始：先核对数据源可达与权限，再查up、指标名称、job/instance标签、时间范围及rate窗口。原始Counter存在但窗口不足两个样本时rate可能为空；标签过滤匹配不到则是空向量，不是数值零。禁止直接用or vector(0)修补所有空图，这会让采集失败看起来业务健康。保存真实表达式、时间窗和数据源UID以便复盘。</p><h3 id="part-1-reset" tabindex="-1">Counter重置与联接 <a class="header-anchor" href="#part-1-reset" aria-label="Permalink to &quot;Counter重置与联接 {#part-1-reset}&quot;">​</a></h3><p>指标Counter重置出现在进程重启或目标替换，rate按序列处理递减；先聚合再rate可能掩盖重置产生错误突增。跨Exporter联接时instance可能包含不同端口，同一主机的node与mysql指标不一定同标签。旧MySQL内存面板按on(instance)联接，匹配错误会空图；应设计稳定主机标识并保证一对一，不能盲目group_left制造多对多结果。</p><h3 id="part-1-units" tabindex="-1">单位与分位数误读 <a class="header-anchor" href="#part-1-units" aria-label="Permalink to &quot;单位与分位数误读 {#part-1-units}&quot;">​</a></h3><p>原内部业务监控资料已移除；请使用本地示例应用生成指标，再验证采集、标签和查询结果。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：rate为空时用零替代能证明无流量吗？</p><details><summary>参考解答</summary><p>不能。可能采样不足、时间范围错、目标缺失或label不匹配，须先核对原始序列及抓取健康。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><p><a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">Prometheus 3.x当前规则文档核对</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/administration/provisioning/" target="_blank" rel="noopener noreferrer">Grafana provisioning核对</a></p></li><li><p><a href="https://prometheus.io/docs/prometheus/2.55/querying/functions/" target="_blank" rel="noopener noreferrer">PromQL函数2.55</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/datasources/prometheus/configure/" target="_blank" rel="noopener noreferrer">Grafana数据源</a></p></li><li><p><a href="https://github.com/prometheus/docs/blob/main/docs/tutorials/understanding_metric_types.md" target="_blank" rel="noopener noreferrer">指标类型官方教程</a></p></li></ul><p>继续阅读<a href="/systems/logging-monitoring/metrics/metric-model#part-2-types">机制</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/application#files">完整实践</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/operations#capacity">运维</a>、<a href="#part-1-empty">诊断</a>与<a href="#part-2-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">面板正常但汇总失真的复盘 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;面板正常但汇总失真的复盘 {#part-2}&quot;">​</a></h2><p>以下演练将Prometheus 指标与 Grafana 面板的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/logging-monitoring/metrics/plus/practice/application#source">配套示例</a>中的指标类型/单位、抓取窗口与数据源 UID。演练未执行。</p><h3 id="part-2-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-2-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-2-incident-scenario}&quot;">​</a></h3><p>每个实例的成功率都接近正常，服务整体指标却与用户反馈明显不符。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-2-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-2-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-2-incident-evidence}&quot;">​</a></h3><ol><li>核对分子和分母是否来自同一时间窗口、过滤条件和请求集合，检查失败请求有没有被漏采。</li><li>对比各实例流量，判断是否错误地平均了实例百分比，而没有先汇总计数。</li><li>检查 counter 重置、抓取缺口、标签变化和面板单位，保留原查询及样本。</li></ol><h3 id="part-2-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-2-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-2-incident-recovery}&quot;">​</a></h3><p>修正聚合表达式和面板说明，保留原版本便于对照。标签调整同时评估序列数量，不能把请求 ID 等无界值直接加入指标标签。</p><p>验收：用一组可手算的不同流量样本核对整体比例，再验证重启和无数据窗口。面板、录制规则与告警使用一致口径。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://prometheus.io/docs/practices/instrumentation/" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-2-exercise" tabindex="-1">基数和比例练习 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;基数和比例练习 {#part-2-exercise}&quot;">​</a></h3><p>指标基数练习：20个实例、5个状态、10个规范route共1000个组合；增加无限request_id为什么危险？参考解答：每个不同ID产生新序列，活跃内存、索引与长期存储随请求增长，抓取更慢并可能反过来丢数据。ID应进入受控日志/trace关联，不作为统计维度。该组合数是上界估算，实际取决于存在的组合。</p><h3 id="part-2-answer" tabindex="-1">汇总与平均练习 <a class="header-anchor" href="#part-2-answer" aria-label="Permalink to &quot;汇总与平均练习 {#part-2-answer}&quot;">​</a></h3><p>指标比例练习：A实例1次失败/1次请求，B实例0次失败/99次请求，整体错误率是多少？参考解答：总失败1/总请求100为1%，直接平均100%与0%得到50%错误。先确定统计对象、时间窗口与过滤标签，再选择聚合顺序。仪表盘与告警应共用口径，不能各自用不同分母解释同一事故。</p><h3 id="part-2-history" tabindex="-1">旧Grafana配置的保留边界 <a class="header-anchor" href="#part-2-history" aria-label="Permalink to &quot;旧Grafana配置的保留边界 {#part-2-history}&quot;">​</a></h3><p>原内部业务监控资料已移除；请使用本地示例应用生成指标，再验证采集、标签和查询结果。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：经典_bucket值可以直接当P95吗？</p><details><summary>参考解答</summary><p>不可以。桶是累计计数，要按le保留聚合后计算分位数估计，桶边界粗还会产生误差。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h3 id="part-2-legacy-links" tabindex="-1">保留原文入口 <a class="header-anchor" href="#part-2-legacy-links" aria-label="Permalink to &quot;保留原文入口 {#part-2-legacy-links}&quot;">​</a></h3><ul><li><a href="/systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources">Grafana多数据源原文</a></li><li><a href="/systems/logging-monitoring/metrics/plus/practice/application#datasource">Grafana使用历史</a></li><li><a href="/systems/logging-monitoring/metrics/plus/ecosystem/监控json">API与MySQL完整旧面板</a></li></ul>',40)])])}const g=a(n,[["render",s]]);export{d as __pageData,g as default};
